    /// Serves a `Server` on a connection (pass it in `CapSlot.export`).
    /// Inherited interfaces dispatch here too (the Server protocol inherits
    /// their requirements; E-order holds for the whole closure).
    public struct Export: ExportHandler {
        public let server: any Server
        public init(_ server: any Server) { self.server = server }
        public func handle(_ call: InboundCall, on connection: isolated RPCConnection) async throws -> CallResponse {
            switch call.interfaceID {
            case MatchmakingService.interfaceID:
                switch call.methodID {
                case MatchmakingService.Method.enqueue.rawValue:
                    let params = try decoding { try MatchmakingService.EnqueueParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.enqueue(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                case MatchmakingService.Method.dequeue.rawValue:
                    let params = try decoding { try MatchmakingService.DequeueParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.dequeue(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                case MatchmakingService.Method.findMatch.rawValue:
                    let params = try decoding { try MatchmakingService.FindMatchParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.findMatch(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                case MatchmakingService.Method.getQueueStats.rawValue:
                    let params = try decoding { try MatchmakingService.GetQueueStatsParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.getQueueStats(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                case MatchmakingService.Method.getMatchResult.rawValue:
                    let params = try decoding { try MatchmakingService.GetMatchResultParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.getMatchResult(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                default:
                    throw RPCError.unimplemented(reason: "MatchmakingService: no such method")
                }
            default:
                throw RPCError.unimplemented(reason: "MatchmakingService: wrong interface")
            }
        }
    }

